def owners_with_pets(db):
    owners = db.query("SELECT * FROM owners")
    if not owners:
        return []
    ids = [o["id"] for o in owners]
    pets = db.query("SELECT * FROM pets WHERE owner_id IN (?)", (ids,))
    by_owner = {}
    for p in pets:
        by_owner.setdefault(p["owner_id"], []).append(p["name"])
