function createCache({ ttlMs, now }) {
  // [[edit]]
  // Store each value with the time it was set. An entry whose age is >= ttlMs
  // is a miss and must be removed. Count hits and misses for stats().
  const store = new Map();
  return {
    get(key) {
      const entry = store.get(key);
      return entry ? entry.value : undefined;
    },
    set(key, value) {
      store.set(key, { value, at: now() });
    },
    invalidate(key) {
      return store.delete(key);
    },
    stats() {
      return { hits: 0, misses: 0, size: store.size };
    },
  };
  // [[/edit]]
}

