function createCache({ ttlMs, now }) {
  const store = new Map();
  let hits = 0;
  let misses = 0;
  return {
    get(key) {
      const entry = store.get(key);
      if (!entry) { misses++; return undefined; }
      if (now() - entry.at >= ttlMs) {
        store.delete(key);
        misses++;
        return undefined;
      }
      hits++;
      return entry.value;
    },
    set(key, value) {
      store.set(key, { value, at: now() });
    },
    invalidate(key) {
      return store.delete(key);
    },
    stats() {
      return { hits, misses, size: store.size };
    },
  };
}

