function cacheKey(namespace, params) {
  const entries = Object.entries(params)
    .filter(([, v]) => v !== undefined)
    .sort(([a], [b]) => (a < b ? -1 : a > b ? 1 : 0));
  return namespace + "|" + entries.map(([k, v]) => `${k}=${v}`).join("&");
}

describe("cacheKey", () => {
  it("formats namespace and sorted pairs", () => {
    expect(cacheKey("seatmap", { venue: 88, show: 4412 })).toBe("seatmap|show=4412&venue=88");
  });
  it("is stable across insertion order", () => {
    expect(cacheKey("seatmap", { show: 4412, venue: 88 }))
      .toBe(cacheKey("seatmap", { venue: 88, show: 4412 }));
  });
  it("omits undefined values", () => {
    expect(cacheKey("seatmap", { venue: 88, tier: undefined })).toBe("seatmap|venue=88");
  });
  it("handles empty params", () => {
    expect(cacheKey("seatmap", {})).toBe("seatmap|");
  });
  it("does not collide for different params", () => {
    expect(cacheKey("seatmap", { venue: 88 })).not.toBe(cacheKey("seatmap", { venue: 89 }));
  });
});
